def payload(depth, salt, max_tokens=96, effort="none", prompt=None):
    if prompt is None:
        lo, hi = 1, depth
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if len(request("/tokenize", {"content": LINE * mid})["tokens"]) <= depth - 120:
                lo = mid
            else:
                hi = mid - 1
        prompt = (
            "Initial code AMBER.\n" + LINE * lo
            + "\nFinal code ORCHID. Reply with the final code, then count from 1 to 30 separated by commas."
        )
    return {
        "model": MODEL,
        "messages": [{"role": "user", "content": prompt}],
        "temperature": 0,
        "seed": 42,
        "reasoning_effort": effort,
        "max_tokens": max_tokens,
        "cache_salt": RUN_TAG + ":" + salt,
    }
